const defaults = require("./defaults");
const fs = require('fs');
const { program } = require('commander');
program
    .name("office-addin-https-reverse-proxy")
    .option("-p, --port <port>", "HTTPS port", defaults.port)
    .option("--httpport <httpport>", "HTTP port", defaults.http_port)
    .option("-c, --certfile <certfile>", "certificiate file path", defaults.certfile)
    .option("-k, --keyfile <keyfile>", "certificate key file path", defaults.keyfile)
    .option("-u, --url <url>", "target url", defaults.url);
program.parse(process.argv);

console.log(`certificate file ${program.certfile}`);
console.log(`key file ${program.keyfile}`);
console.log(`https://localhost:${program.port} for ${program.url}`);
console.log("");

[program.certfile, program.keyfile].forEach((file) => {
    if (!fs.existsSync(file)) {
        console.error(`certificate ${file} does not exist. Please use 'npx office-addin-dev-certs install --days 365' to create one.`);
        process.exit(-1);
    }
});

const proxy = require('redbird')({
    port: program.httpport,
    xfwd: true,
    ssl: {
      port: program.port,
      cert: program.certfile,
      key: program.keyfile
    }
  });

proxy.register("localhost", program.url);
